// Feature 004 — the "Erosion over stack (imported meshes)" seed template. Rebuilds the SAME
// geology as the parametric "Erosion over conformal stack" repro (a 2-unit erode cover over a
// 3-bed conformal stack) entirely from imported ~100k-vertex .obj meshes, referenced by
// `objPath` and hydrated on seed (main.tsx onSeed → hydrateMeshPaths). This pins that:
//   1. seeding hydrates + fits all five imported surfaces (status reaches done, no error), and
//   2. every surface renders geometry (each imported surface is its own series in __surfaces).
// The .obj fixtures are generated by `cargo test -p geofield --test gen_erosion_meshes --
// --ignored`; this test is skipped if they are absent (they are gitignored per-machine assets).

import { test, expect, type Page } from "@playwright/test";
import { existsSync } from "node:fs";
import { fileURLToPath } from "node:url";

// The five meshes must be present under public/meshes/ for the template to hydrate.
const MESH_DIR = fileURLToPath(new URL("../public/meshes/", import.meta.url));
const MESHES = [
  "erosion-stack-bed1.obj",
  "erosion-stack-bed2.obj",
  "erosion-stack-bed3.obj",
  "erosion-stack-erosion.obj",
  "erosion-stack-cover.obj",
];

/** Total triangle count across all rendered surfaces (any series). */
function totalTriCount(page: Page): Promise<number> {
  return page.evaluate(() => {
    const s = (window as unknown as { __surfaces?: { series: number; indices: Uint32Array }[] })
      .__surfaces ?? [];
    return s.reduce((n, x) => n + x.indices.length / 3, 0);
  });
}

/** How many DISTINCT series rendered geometry (each imported surface is its own series). */
function seriesWithGeometry(page: Page): Promise<number> {
  return page.evaluate(() => {
    const s = (window as unknown as { __surfaces?: { series: number; indices: Uint32Array }[] })
      .__surfaces ?? [];
    return new Set(s.filter((x) => x.indices.length > 0).map((x) => x.series)).size;
  });
}

test("the imported-mesh erosion-over-stack template hydrates, fits, and renders every surface", async ({
  page,
}) => {
  test.skip(
    !MESHES.every((m) => existsSync(MESH_DIR + m)),
    "erosion-stack-*.obj fixtures absent — regenerate with `cargo test -p geofield --test gen_erosion_meshes -- --ignored`",
  );

  // Five ~100k-vert meshes fit + contour; give the whole pipeline generous time.
  test.setTimeout(300_000); // Surfaces fit + Solids re-mesh of five 100k-vert meshes is heavy.

  await page.goto("/");
  await page.getByTestId("seed-template").selectOption("erosion-over-stack-imported");

  // Seeding hydrates the .obj paths, fits a field through each mesh, and meshes the scene.
  await expect(page.getByText("status: done")).toBeVisible({ timeout: 150_000 });
  await expect(page.getByTestId("stale-scrim")).toHaveCount(0, { timeout: 150_000 });

  // Every one of the five imported surfaces is its own series and must render geometry.
  expect(await seriesWithGeometry(page), "all five imported surfaces rendered").toBe(5);
  expect(await totalTriCount(page), "the scene has substantial geometry").toBeGreaterThan(1000);

  // Export OBJ is enabled only when surfaces.length > 0 — a live guard that geometry is in-scene.
  await expect(page.getByTestId("export-obj")).toBeEnabled();

  // The template names its surfaces; the hierarchy shows the erosion surface (the erode role that
  // must truncate the beds below it).
  await expect(page.getByText("erosion surface")).toBeVisible();

  // --- Solids: each of the five surfaces must yield its OWN below-rock SLAB volume, not an
  //     overlapping full-height prism. Independent conformable imported contacts now subtract the
  //     next-older contact (Stack::older_imported_contact_prism) → five distinct volumes. Before the
  //     fix only ~2 survived (interpenetrating prisms), so this pins the stacking regression.
  await page.getByTestId("render-toggle").click();
  // The Solids re-mesh of five 100k-vert meshes + Manifold booleans is slow; wait for status to
  // LEAVE done (re-run started) so we don't read the stale Surfaces payloads, then for it to return.
  await page
    .waitForFunction(() => (window as { __statusLog?: string[] }).__statusLog?.slice(-1)[0] !== "done", { timeout: 10_000 })
    .catch(() => {});
  await expect(page.getByText("status: done")).toBeVisible({ timeout: 120_000 });
  await expect(page.getByTestId("stale-scrim")).toHaveCount(0, { timeout: 120_000 });
  // Now the payloads are solids (each carries a `unit`).
  await expect
    .poll(
      () =>
        page.evaluate(() => {
          const s = (window as { __surfaces?: { unit?: number }[] }).__surfaces ?? [];
          return s.length > 0 && s.every((x) => x.unit !== undefined && x.unit !== null);
        }),
      { timeout: 120_000 },
    )
    .toBe(true);

  // Every one of the five imported surfaces (each its own series) must contribute a below-rock
  // (unit 0) slab. Before the fix only 2 series survived: the conformable beds overlapped as full-
  // height prisms, and the erode clip's below-solid dropped the beds beneath the erosion. This pins
  // both the slab-subtraction and the mesh-prism erode-clip.
  const seriesWithSlab = await page.evaluate(() => {
    const s = (window as { __surfaces?: { series: number; unit?: number; indices: Uint32Array }[] })
      .__surfaces ?? [];
    return new Set(
      s.filter((x) => x.indices.length > 0 && x.unit === 0).map((x) => x.series),
    ).size;
  });
  expect(seriesWithSlab, "all five imported surfaces yield a below-rock slab in Solids").toBe(5);
});
